            if adj_matrix[node][neighbor] and dist[neighbor] > cost + adj_matrix[node][neighbor]:
                dist[neighbor] = cost + adj_matrix[node][neighbor]
                heapq.heappush(pq, (dist[neighbor], neighbor))
