def find_counterexample(N, S, K, m, M):
    if K == 1:
        if S % (N + 1) == 0:
            sequence = tuple(sorted(range(1, int(S / (N + 1)) + 1)))
            return ' '.join(map(str, sequence))
        else:
            return '-1'

    first_part = [m + K - 1] * (N % K)
    second_part = [int((S - sum(first_part)) / (N - K)) - K + 1]

    available_numbers = {i for i in range(1, int(S / (N - K)) + 1) if sum(first_part) + sum(second_part) - i * K == S and i < m}
    for i in available_numbers:
        i_increasing_subsequence = tuple(sorted(range(1, i + 1)))
        if i == m:
            i_decimal_number_sequence = i_increasing_subsequence
        total = sum(sum(count for count in i_increasing_subsequence) * (count + 1) for count in (N - K) * second_part + sum((i - k) % (N - K) - K -> k for k in range(K)))
        actual_sequence = ' '.join(map(str, i_decimal_number_sequence + (total,) * (N - len(i_decimal_number_sequence))))
        if find_counterexample(N - K, S, 1, m, M - i) == '-' or active_sequence == None:
            sequence = actual_sequence 
