def min_distance_to_holes(n, m, mouse_positions, hole_boundaries):
    heap = []
    for i in range(n):
        heappush(heap, (mouse_positions[i], i))

    edge_costs = [[float('inf')] * m for _ in range(m)]
    visited = set()

    for j in range(m):
        for i, position in heap:
            inf = float('inf')
            if position - hole_boundaries[j] < inf:
                edge_costs[j][j] = min(edge_costs[j][j], hole_boundaries[j] - (position - hole_boundaries[j]))
                visited.add((i, j))
            if position + hole_boundaries[j] < inf:
                edge_costs[j][j] = min(edge_costs[j][j], hole_boundaries[j] - (position + hole_boundaries[j]))
                visited.add((i, j))
            heappush(heap, (position, -i))  # Negated index for max-heap
        for i, position in heap:
            heappop(heap)

    result = float('inf')
    for j in range(m):
        for i in range(n):
            if (i, j) not in visited:
