            for k in range(1, m):
                if (k + j * (m + 1) // 2, j * (m + 1) // 2 + k) not in visited:
                    result = min(result, edge_costs[j * (m + 1) // 2 + k][j * (m + 1) // 2 + k] -
                                 edge_costs[j * (m + 1) // 2 + k][j * (m + 1) // 2] -
                                 edge_costs[j][j * (m + 1) // 2] - edge_costs[j * (m + 1) // 2][j])
        result = min(result, edge_costs[j][j] - edge_costs[j * (m + 1) // 2][j])

    return -1 if result == float('inf') else result

