def count_correct_substrings(s):
    n = len(s)
    balance = [0] * n
    stack = []

    for i in range(n):
        if s[i] == '(':
            stack.append(i)
            balance[i] = 1
        elif s[i] == ')':
            if stack:
                j = stack.pop()
                if balance[j] == 1:
                    balance[i] = balance[j] + 1
                else:
                    balance[i] = balance[j] - 1
                if not stack and balance[i] == 0:
                    balance[i] = -1
            else:
                balance[i] = -1

    stack.clear()
    balance[n-1] = 1
    counter = 0

    for i in range(n-2, -1, -1):
        if i == s[i] and not stack:
            counter += 1

        if balance[i] == -1:
            continue

        while stack and (balance[i] < 0 or balance[i] < balance[stack[-1]]):
            diff = balance[i] - balance[stack[-1]] + 1

            if diff == 1:
                counter -= 1
            elif diff < 1:
                counter -= diff
                break
            stack.pop()

        if balance[i] == -1:
            continue

        if balance[i] == 0:
            counter += (balance[i-1] - balance[i+1]) // 2 + 1

        while stack and balance[stack[-1]] <= balance[i]:
            diff = balance[stack[-1]] - balance[i] + 1
            if diff == 1:
                counter -= 1
            elif diff < 1:
                counter -= diff
                stack.pop()
            else:
                balance[stack[-1]] = balance[i] - 1
                stack.pop()

        stack.append(i)

    return counter

