from collections import defaultdict

def find_modes_required(x, n, items):
    mode_counts = defaultdict(set)
    for item, pages in items:
        for i in range(1, 1001 * min(pages, 1000)):
            for p in range(1, pages + 1):
                if p * i > pages:
                    break
                if p * i <= x:
                    mode_counts[p * i].add((item, i))
                else:
                    break
    def check_modes(m):
        total = 0
        items_seen = set()
        for m_items, t_pages in sorted(mode_counts, reverse=True):
            for item, i in m_items:
                if i in mode_counts:
                    valid = True
                    for other_item, other_i in mode_counts[i]:
                        if other_item in items_seen - m_items:
                            valid = False
                            break
                    if not valid:
                        break
                    items_seen |= m_items
                break
            else:
                if t_pages >= m:
                    total += i
                else:
                    return False, defaultdict(int)
            if total > x or total < 2:
                return False, defaultdict(int)
        return False, defaultdict(int)
    for m in range(1, 1000001):
        if check_modes(map(m, range(n)))[0]:
            return m
    return -1

