    plan_counts = [1] * (n - 1)
    for _ in range(2):
        new_plan_counts = [1] * (n - 1)
        start_city_states = {city: (0, False) for city in cities}
        for ii, city in enumerate(cities):
            if isinstance(ctx := start_city_states[city][ii], int):
                continue
            state = ctx[0]
            can_change_state = state[1]
            can_change = [(city, v) for city in start_city_states for v in routes if v[0] == state[1] and v[1] == city]
            for _, v in can_change:
                can_change_state = False
                for nei in adj[v[0]]:
                    if len(adj[nei]) == 2:
                        new_routes = set()
                        for nei_v in adj[nei]:
