MOD = 10**9 + 7

def count_plan(scc, n, allow_zero, allow_all, one_to_mxn):
    scc_count = [[] for _ in range(n)]
    for i in range(n):
        scc_count[scc[i]].append(i)

    dp = [0] * (n + 1)
    dp[0] = 1

    for size in range(1, n + 1):
        for subset_len in range(size, -1, -1):
            if not dp[subset_len]:
                continue

            if one_to_mxn:
                for child in scc_count[subset_len]:
                    if subset_len + 1 <= one_to_mxn:
                        dp[size] += dp[subset_len] * ways(child, allow_zero, allow_all) % MOD

    return dp[size]

def ways(usages, allow_zero=True, allow_all=False):
    _d = {0: 0, 1: 1, 2: 1, 3: 2, 4: 3}
    letters = {0: [], 1: [0, 1], 2: [0, 2], 3: [1, 2]}
    dp = {0: (1 if allow_zero else 0), 1: _d[1], 2: _d[2], 3: _d[3]}

    for usage in range(4, 401):
        new_letters = letters[usage - 3]
        for index in new_letters:
            if usage in dp:
                dp[usage] += dp[usage - new_letters[index]]
            else:
                dp[usage] = dp[usage - new_letters[index]]
            dp[usage] %= MOD

    return dp[usage]

