def ncr(n, k, memo):
    if k == 0:
        return 1
    if k == 1 or k == n:
        return n
    if memo[n][k] == 0:
        memo[n][k] = ncr(n, k-1, memo) * (n - k + 1) % 1000000007
    else:
        memo[n][k] = memo[n][k] * (n - k + 1) % 1000000007
    return memo[n][k]

def num_beautiful_trees(n, m, a, b):
    count = [[0 for i in range(n+1)] for j in range(n+1)]
    memo = [[0 for i in range(n+1)] for j in range(n+1)]

    for c in range(m+1):
        for d in range(n-c-1):
            for e in range(c, n-c):
                count[c][d] = (count[c][d] + ncr(e + 2*d, 2*d) * ncr(n-e-2*d, 2*d) % 1000000007) % 1000000007 

    for c in range(n+1):
        for d in range(n+1):
            count[c][d] = count[c][d]*(ncr(n-c, c) % 1000000007*(ncr(c+d, c*d) % 1000000007)) % 1000000007
