    if K > 2 and m <= 2 and N % K == 0:
        return sorted(range(max(1, m), max(2, m + N - K)))[(N - K - 1) / 2]

    # For other cases, we use a different array for K=1, and compute the medians using the formula
    elif K == 1 or N % K == 0:
