def is_balanced_sequence(sequence):
    balance = 0
    for char in sequence:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_correct_subsequences(s):
    sequence_to_index = {}
    sequence_count = {'(': 0, ')': 0}
    for i, char in enumerate(s):
        if char == '(':
            sequence_to_index[i] = sequence_count['(']
            sequence_count['('] += 1
        else:
            sequence_to_index[i] = sequence_count[')']
            sequence_count[')'] += 1

    subsequence_lengths = {}
    for i in range(len(s)):
        if s[i] in sequence_to_index:
            if s[i] not in subsequence_lengths:
                subsequence_lengths[s[i]] = []
            subsequence_lengths[s[i]].append(i)

    correct_count = 0
    for substr in subsequence_lengths.values():
        for seq in substr:
            if is_balanced_sequence(s[seq:seq+1]):
                correct_count += 1

    return correct_count

