def count_beautiful_trees(n, m, a, b):
    graph, n = generate_graph(n, m, a, b)
    memo = {}

    def dfs(node, parent, level):
        if level == 1:
            return 1
        if node in memo:
            return memo[node]

        total_trees = 1
        for neighbor in graph[node]:
            if neighbor != parent:
                total_trees += dfs(neighbor, node, max(1, level + 1)) * dfs(neighbor, node, min(level+1, m+1)) % (10**9 + 7)

        memo[node] = total_trees
        return total_trees

    return dfs(1, None, 1) % (10**9 + 7)

