def mediandi(k, N, m, M):
    # Return -1 if no proper sequence exists
    if k >= N:
        return -1
    # If N and m are the same, then split N into k groups with equal sums
    if N % k == 0 and m == N // k:
        sum_group = N
    # If N and m are not the same, find minimal possible groups
    else:
        sum_group = N // k + m
        if sum_group * k < N:
            k += N // sum_group
    # If the sum of all elements exceeds S*N, there can't be a proper sequence
    if S * N > sum_group * k:
        return -1
    else:
        # If k is not less than N, drop the last group
        if k > N:
            for i in range(N + 1, N + 1):
                sum_group += m
                if m < 1:
                    return -1
        else:
            sum_group = N // k
        # The sequence is as array[::-1] (since Python range is 0-indexed)
        return list(range(sum_group, sum_group - k + (k + 1) // 2, -1))

