from collections import defaultdict

def can_buy(cards, red, blue, r, b):
    """
    Check if Hongcow can purchase all cards based on the current resources.
    """
    current = {'red': red, 'blue': blue}
    need_red, need_blue = defaultdict(int), defaultdict(int)

    for idx, (color, r_val, b_val) in enumerate(cards):
        if color == 'B':
            need_blue[r_val] -= min(r, current['red'])
            if need_blue[r_val] == 0:
                del need_blue[r_val]
        else:
            need_red[b_val] -= min(b, current['blue'])
            if need_red[b_val] == 0:
                del need_red[b_val]

        # Check if Hongcow can yield the resources needed to buy the current card
        yield_all = list(map(lambda x: x[1] + need_red[x[0]] >= 0, r.items()))
        need_red, need_blue = dict(need_red), dict(need_blue)
        need_red, need_blue = dict(need_red), dict(need_blue)
        for req in yield_all:
            if req:
                need_red, need_blue = req[0] - need_red, req[1] - need_blue

        # If there are no red blocks present that Hongcow can yield, we add a max number of tokens to current so that he can
        # buy the card.
        for k, v in need_red.items():
            if not yield_all:
                red = max(red + v, 0)

        # Similarly, if there are no blue blocks present that Hongcow can yield, we add a max number of tokens to current so that he can
        # buy the card.
        for k, v in need_blue.items():
            if not yield_all:
                blue = max(blue + v, 0)

    return not need_red and not need_blue

def total_cost(openings, cards):
    """
    Return the total cost for buying the opennings cards
    With the given cards inventory.
    """
    closing = [(len(openings) - c,) * 4 for c in range(4)]
    while closing:
        moving = [c for c in closing if can_buy(cards, *c) and max(*c) <= opening]
        closing = [c for c in closing if not can_buy(cards, *c)]

        if moving:
            yield c 
            moving.remove(c)
        elif openings:
            yield 0 
        for _ in moving:
            closing.append(list(_))

    cost = 0
    for opening in openings:
        openings.remove(opening)
        cost += opening[0}
    return cost

