import bisect

def find_counterexample(N, S, K, m, M):
    if N <= 2 * (K + 1):
        return -1

    remaining = S - (N // 2 * m + N % 2 * m)
    closest = 1
    for i in range(1, M - 1):
        if i * K <= remaining and (remaining - i * K) % K == 0:
            diff = abs((remaining // K - i) - ((remaining % K) // K))
            if diff < bisect.bisect_left(bisect.bisect_left(bisect.bisect_left(sorted(set(range(K, S + 1, K))), closest), remaining // K), closest) - 1 and (i + K + sum(sorted(set(range(i, S + 1, K)))) > remaining and sum(range(1, i + 1)) > remaining % K):
                closest = i
                remaining -= i * K

    return [min(N % 2 + closest, per) for per in range(N // 2 + 1)] + [N % 2 + closest]

