def find_min_modes(x, a):
    start_numbers = defaultdict(list)
    for ai in a:
        for i in range(1, ai//2 + 1):
            start_numbers[ai].append(i)
    for ai in a:
        if len(start_numbers[ai]) < 2:
            return -1
    modes = defaultdict(int)
    known_modes = set(find_modes(a))
    for start in start_numbers[1]:
        ai = 1
        while ai <= x:
            found = False
            for bi in range(1, (x+1)//ai + 1):
                if modes[bi] < len(start_numbers[ai]):
                    continue
                prev_ai = ai
                ai = min(ai + bi, x//bi)
                if modes[bi] == len(start_numbers[ai]):
                    found = True
                    break
            if not found:
                return -1
            if modes[ai] == 1:
                modes[ai] += 1
                if modes[ai] == start_numbers[ai][-1]:
                    modes[ai] = 1
                else:
                    modes[ai] = prev_ai
                modes[ai * bi] = len(start_numbers[ai])
    return len(known_modes)

