from collections import defaultdict

def min_distance(n, m, mice, holes):
    min_holes = [float('inf')] * m
    distances = defaultdict(set)
    for i, (x, j, cj) in enumerate(zip(mice, holes)):
        for j, c in enumerate(j):
            min_holes[j] = min(min_holes[j], c)
            distances[(j, dist(x, cx, cj))].add(i + dist(x, cx, c))

    # Initialize distances to the first hole with the smallest number of mice
    min_holes[0] = 0
    for i, (_, j) in enumerate(holes):
        min_holes[j] += dist(i, j, min_holes[j])
        distances[(j, dist(i, j, min_holes[j]))] = []
        for goal in sorted(distances.keys()):
            if distances[goal][-1] >= i:
                min_holes[goal] = i
                minimum = min(holes[0] - holes[j], i)
                for precedence in range(minimum + 1, i):
                    dif = min(min_holes[holes[j]], i - precedence)
                    if precedence - dif <= 0:
                        break
                    try:
                        del distances[goal][precedence - dif]
                        min_holes[goal] += dif
                    except IndexError:
                        pass

    if not distances:
        return -1
    return min(min_holes)

